<span class="line">  <span class="token keyword">const</span> operatorId <span class="token operator">=</span> req<span class="token punctuation">.</span>operator<span class="token punctuation">.</span>id<span class="token punctuation">;</span>                  <span class="token comment">// 앱 인증 미들웨어가 채운 값</span></span>
