<span class="line">      <span class="token literal-property property">channelEndpoint</span><span class="token operator">:</span> <span class="token keyword">this</span><span class="token punctuation">.</span>session<span class="token punctuation">.</span>wssEndpoint<span class="token punctuation">,</span></span>
